-- ============================================================
-- 0005_backfill_risp.sql
-- 過去にスクレイピング済みの試合データへ得点圏(risp)フラグを遡及反映
--
-- 背景: 取得元サイトは打席結果セルに class='tktnkn'（凡例:「得点圏に
-- ランナーあり」）が付くかどうかで得点圏を示しているが、
-- scripts/parseGamePage.mts はこれまでこの属性を読み取っておらず、
-- 過去にスクレイピングした全打席で得点圏打率が常に.000になっていた。
-- パーサー修正後に全試合を再取得・再パースし、risp以外の内容が完全一致
-- することを確認した上で、plate_results だけを更新する。
--
-- 実行方法: 0001〜0004と同様、Supabase ダッシュボードの SQL Editor に
-- 貼り付けて実行。
-- ============================================================

update public.game_batting_stats set plate_results = '[{"inning":1,"result":"死球","run":true,"steal":2},{"inning":2,"result":"左安","steal":1,"risp":true},{"inning":4,"result":"左三","run":true},{"inning":5,"result":"四球","run":true,"steal":1,"risp":true}]'::jsonb where game_id = 'game-10' and player_id = '石ちゃん';
update public.game_batting_stats set plate_results = '[{"inning":1,"result":"三ゴ","risp":true},{"inning":2,"result":"捕内","risp":true},{"inning":4,"result":"右三","rbi":1,"run":true,"risp":true},{"inning":5,"result":"左本","rbi":3,"run":true}]'::jsonb where game_id = 'game-10' and player_id = '4カドの峰';
update public.game_batting_stats set plate_results = '[{"inning":1,"result":"四球","steal":1,"risp":true},{"inning":2,"result":"中飛","risp":true},{"inning":4,"result":"遊内","run":true,"steal":1,"risp":true},{"inning":5,"result":"四球","steal":1}]'::jsonb where game_id = 'game-10' and player_id = 'レジェンド';
update public.game_batting_stats set plate_results = '[{"inning":1,"result":"中犠","rbi":1,"risp":true},{"inning":2,"result":"三飛","risp":true},{"inning":4,"result":"四球","run":true,"risp":true},{"inning":5,"result":"三ゴ","advancing_hit":true,"risp":true}]'::jsonb where game_id = 'game-10' and player_id = 'アニキ';
update public.game_batting_stats set plate_results = '[{"inning":1,"result":"四球","steal":1,"risp":true},{"inning":3,"result":"三振"},{"inning":4,"result":"四球","run":true,"risp":true},{"inning":5,"result":"三振","risp":true}]'::jsonb where game_id = 'game-10' and player_id = 'エース';
