update public.game_batting_stats set plate_results = '[{"inning":1,"result":"左飛","risp":true},{"inning":3,"result":"左安"},{"inning":4,"result":"遊ゴ","rbi":1,"risp":true}]'::jsonb where game_id = 'game-10' and player_id = 'さかちゃん';
update public.game_batting_stats set plate_results = '[{"inning":2,"result":"遊内","steal":1},{"inning":3,"result":"左安"},{"inning":4,"result":"三ゴ","risp":true}]'::jsonb where game_id = 'game-10' and player_id = 'ラッキーボーイ';
