-- 上記のrisp反映作業の安全確認（risp以外の差分が無いことのチェック）で偶然発見した、
-- risp とは無関係の2件の実データ抜け漏れ（game-140は今セッション中に取り込んだばかりだが、
-- 取り込み後に実サイト側の記録が追記/修正されていたと見られる）。
-- ひろぽん: 7回の「遊内」に盗塁フラグが抜けていた。
update public.game_batting_stats
set plate_results = '[{"inning":1,"result":"一ゴ"},{"inning":2,"result":"遊飛"},{"inning":5,"result":"三邪"},{"inning":7,"result":"遊内","steal":1}]'::jsonb,
    steals = 1
where game_id = 'game-140' and player_id = 'ひろぽん';

-- ラッキーボーイ: 2回の「遊内」に打点フラグが抜けていた。
update public.game_batting_stats
set plate_results = '[{"inning":2,"rbi":1,"result":"遊内","run":true,"steal":1},{"inning":4,"result":"投ゴ"},{"inning":6,"result":"三振"}]'::jsonb,
    rbi = 1
where game_id = 'game-140' and player_id = 'ラッキーボーイ';
